/// Detect the syntax based on, in order:
///  1. Syntax mappings with [MappingTarget::MapTo] and [MappingTarget::MapToUnknown]
///     (e.g. `/etc/profile` -> `Bourne Again Shell (bash)`)
///  2. The file name (e.g. `Dockerfile`)
///  3. Syntax mappings with [MappingTarget::MapExtensionToUnknown]
///     (e.g. `*.conf`)
///  4. The file name extension (e.g. `.rs`)
///
/// When detecting syntax based on syntax mappings, the full path is taken
/// into account. When detecting syntax based on file name, no regard is
/// taken to the path of the file. Only the file name itself matters. When
/// detecting syntax based on file name extension, only the file name
/// extension itself matters.
///
/// Returns [Error::UndetectedSyntax] if it was not possible detect syntax
/// based on path/file name/extension (or if the path was mapped to
/// [MappingTarget::MapToUnknown] or [MappingTarget::MapExtensionToUnknown]).
/// In this case it is appropriate to fall back to other methods to detect
/// syntax. Such as using the contents of the first line of the file.
///
/// Returns [Error::UnknownSyntax] if a syntax mapping exist, but the mapped
/// syntax does not exist.
pub fn get_syntax_for_path(
    &self,
    path: impl AsRef<Path>,
    mapping: &SyntaxMapping,
) -> Result<SyntaxReferenceInSet> {
    self.get_syntax_for_path_with_ignored_suffixes(path, mapping, &[])
}

pub fn get_syntax_for_path_with_ignored_suffixes(
    &self,
    path: impl AsRef<Path>,
    mapping: &SyntaxMapping,
    ignored_suffixes: &[String],
) -> Result<SyntaxReferenceInSet> {
    let path = path.as_ref();
    let path_for_error = path.to_string_lossy().into_owned();
    let mapping_candidate = Candidate::new(path);
    let file_name_os = path.file_name();
    let file_name_candidate = file_name_os.map(Candidate::new);
    let mapping_entries = mapping.mappings();
    let mapping_count = mapping_entries.len();
    let mut syntax_match: Option<MappingTarget> = None;
    let mut remaining = mapping_count;

    while remaining > 0 {
        remaining -= 1;
        let (glob, target) = &mapping_entries[remaining];
        let matched_full_path = glob.is_match_candidate(&mapping_candidate);
        if matched_full_path {
            syntax_match = Some(*target);
            break;
        } else if let Some(ref file_candidate) = file_name_candidate {
            let matched_file_name = glob.is_match_candidate(file_candidate);
            if matched_file_name {
                syntax_match = Some(*target);
                break;
            }
        }
    }

    if let Some(MappingTarget::MapToUnknown) = syntax_match {
        return Err(Error::UndetectedSyntax(path_for_error.clone()));
    }

    if !self.syntax_set_cell.filled() {
        let loaded_syntax_set = match &self.serialized_syntax_set {
            SerializedSyntaxSet::FromBinary(data) => {
                let compressed = COMPRESS_SYNTAXES;
                let binary_data: &[u8] = *data;
                let integrated_syntax_set = from_binary(binary_data, compressed);
                integrated_syntax_set
            }
            SerializedSyntaxSet::FromFile(cache_path) => {
                let description = "syntax set";
                let compressed = COMPRESS_SYNTAXES;
                let cache_display = cache_path.to_string_lossy();
                let load_error = format!(
                    "Could not load cached {} '{}'",
                    description, cache_display
                );
                let parse_error = format!("Could not parse cached {}", description);
                let contents = fs::read(cache_path).map_err(|_| load_error)?;
                let content_bytes = &contents[..];
                let parsed = asset_from_contents(content_bytes, description, compressed)
                    .map_err(|_| parse_error)?;
                parsed
            }
        };
        let _ = self.syntax_set_cell.fill(loaded_syntax_set);
    }

    let syntax_set = self.get_syntax_set()?;

    if let Some(MappingTarget::MapTo(syntax_name)) = syntax_match {
        if let Some(syntax) = syntax_set.find_syntax_by_name(syntax_name) {
            let mapped_syntax = SyntaxReferenceInSet {
                syntax,
                syntax_set,
            };
            return Ok(mapped_syntax);
        } else {
            let unknown_syntax = syntax_name.to_owned();
            return Err(Error::UnknownSyntax(unknown_syntax));
        }
    }

    let file_name = file_name_os.unwrap_or_default();
    let file_path = Path::new(file_name);
    let extension_os = file_path.extension();
    let extension_token = extension_os.and_then(|ext| ext.to_str()).unwrap_or("");
    let ignored_suffixes = IGNORED_SUFFIXES
        .iter()
        .copied()
        .chain(ignored_suffixes.iter().map(String::as_str));

    if let Some(file_str) = file_path.to_str() {
        if file_str.is_empty() {
            if let Some(syntax) = syntax_set.find_syntax_by_extension(file_str) {
                let empty_name_syntax = SyntaxReferenceInSet {
                    syntax,
                    syntax_set,
                };
                return Ok(empty_name_syntax);
            }
        } else {
            if let Some(syntax) = syntax_set.find_syntax_by_extension(file_str) {
                let file_name_syntax = SyntaxReferenceInSet {
                    syntax,
                    syntax_set,
                };
                return Ok(file_name_syntax);
            } else {
                for suffix in ignored_suffixes.clone() {
                    if let Some(stripped_filename) = file_str.strip_suffix(suffix) {
                        let stripped_os = OsStr::new(stripped_filename);
                        if let Some(syntax) = self.get_syntax_for_file_name(stripped_os)? {
                            return Ok(syntax);
                        } else {
                            break;
                        }
                    }
                }
            }
        }
    }

    if let Some(MappingTarget::MapExtensionToUnknown) = syntax_match {
        return Err(Error::UndetectedSyntax(path_for_error.clone()));
    }

    if let Some(syntax) = syntax_set.find_syntax_by_extension(extension_token) {
        let extension_syntax = SyntaxReferenceInSet {
            syntax,
            syntax_set,
        };
        return Ok(extension_syntax);
    }

    if let Some(file_str) = file_path.to_str() {
        for suffix in ignored_suffixes {
            if let Some(stripped_filename) = file_str.strip_suffix(suffix) {
                let stripped_os = OsStr::new(stripped_filename);
                if let Some(syntax) = self.get_syntax_for_file_extension(stripped_os)? {
                    return Ok(syntax);
                } else {
                    break;
                }
            }
        }
    }

    Err(Error::UndetectedSyntax(path_for_error))

